p='work/test-resident-caller-helpers.py';s=open(p).read()
s=s.replace("a=Asm();a.emit('2f032f0220394199d590');a.branch", "a=Asm();a.emit('2f032f020caf0000009e000c');a.branch('6600','failure');a.emit('20394199d590');a.branch")
s=s.replace("for kind in ['new','additive','rejected','replace','off','unknown_event','missing_context','not_ready','null_owner','bad_magic']:", "for track,kind in [(t,k) for t in range(4) for k in ['new','additive','rejected','replace','off','unknown_event','missing_context','not_ready','null_owner','bad_magic']]:")
s=s.replace('REC=OWNER+0x14c30','REC=OWNER+0x14c30+track*16').replace('oldword=0x80000080;newword=0x80000082','oldword=0x80000080|(track<<13);newword=0x80000082|(track<<13)')
s=s.replace('setup_call(m)\n oldid=', 'setup_call(m,track=track)\n oldid=')
s=s.replace('oldid=m.read(STATE+24,4)','oldid=m.read(STATE+track*40+24,4)')
s=s.replace("[(4,1),(8,0),(12,", "[(4,1),(8,track),(12,")
s=s.replace('m.write(RETAINED+64,4,oldid)','m.write(RETAINED+track*72+64,4,oldid)')
s=s.replace('m.read(RETAINED+64,4)==ret','m.read(RETAINED+track*72+64,4)==ret')
s=s.replace("(REC,ret,0)","(REC,ret,track)").replace("replay=={'d0':0,'a0':0x41345ef8}","replay=={'d0':track,'a0':0x41345ef8}")
s=s.replace("{'kind':kind,'setup_return'", "{'track':track,'kind':kind,'setup_return'")
s=s.replace("'Only synth track zero stock caller exercised'", "'All four synth tracks; controlled single-note mode one and empty voice-stop mask'")
open(p,'w').write(s)
